$ErrorActionPreference = 'Stop'
$repo=Split-Path $PSScriptRoot -Parent
Push-Location $repo
try {
    & (Join-Path $PSScriptRoot 'Test-CheckProcess.ps1')
    & (Join-Path $PSScriptRoot 'Test-SceneRunnerCache.ps1')
    & (Join-Path $PSScriptRoot 'Test-PackageMarker.ps1')
    $vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Installer/vswhere.exe'
    $vsPath=& $vswhere -latest -products '*' -property installationPath
    $compiler=Join-Path $vsPath 'MSBuild/Current/Bin/Roslyn/csc.exe'
    $pia=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Shared/Visual Studio Tools for Office/PIA/Office15'
    New-Item -ItemType Directory -Force artifacts/demo-contracts | Out-Null
    & $compiler /nologo /debug:pdbonly /langversion:7.3 /target:exe /main:DemoContractTests /out:artifacts/demo-contracts/DemoContractTests.exe "/link:$pia/office.dll" "/link:$pia/Microsoft.Office.Interop.PowerPoint.dll" /r:System.IO.Compression.dll /r:System.IO.Compression.FileSystem.dll /r:Microsoft.CSharp.dll /r:System.Windows.Forms.dll /r:System.Drawing.dll /r:System.Runtime.Serialization.dll /r:System.Xml.Linq.dll apps/powerpoint-vsto/TemplateCatalog.cs apps/powerpoint-vsto/TemplateLibrary.cs apps/powerpoint-vsto/LocalLibraryGallery.cs apps/powerpoint-vsto/LocalLibraryWorkspace.cs src/Library.Core/*.cs tests/library/LegacyLibraryCacheFixture.cs tests/library/LibraryBrowserTests.cs tests/library/GalleryTests.cs tests/library/PiidxGalleryTests.cs tests/library/piidx/PiidxSourceTests.cs tests/library/TemplateFidelity.cs tests/library/TemplateFidelityTests.cs tests/library/TemplateLibraryTests.cs apps/powerpoint-vsto/DemoRibbon.cs apps/powerpoint-vsto/DemoApi.cs apps/powerpoint-vsto/RibbonIcons.cs apps/powerpoint-vsto/NativeFormatting.cs apps/powerpoint-vsto/PresentationQuality.cs apps/powerpoint-vsto/NativeSeriesControls.cs apps/powerpoint-vsto/NativeChartControls.cs apps/powerpoint-vsto/MappedLinkOperations.cs apps/powerpoint-vsto/ExcelRangeMapping.cs apps/powerpoint-vsto/ChartAnnotations.cs apps/powerpoint-vsto/ProductivityTools.cs apps/powerpoint-vsto/XmlPartUpdates.cs apps/powerpoint-vsto/ContextPanelModel.cs apps/powerpoint-vsto/ContextFormatting.cs apps/powerpoint-vsto/ContextChartFormatting.cs apps/powerpoint-vsto/ContextSelectionBridge.cs apps/powerpoint-vsto/ContextPropertiesView.cs apps/powerpoint-vsto/ContextPropertiesController.cs apps/powerpoint-vsto/ContextActionRouter.cs apps/powerpoint-vsto/ElementCommands.cs apps/powerpoint-vsto/IndicatorElements.cs apps/powerpoint-vsto/UniversalConnectors.cs apps/powerpoint-vsto/TextShapeElements.cs apps/powerpoint-vsto/ProcessFlowTools.cs apps/powerpoint-vsto/ChapterAgendaModel.cs apps/powerpoint-vsto/ChapterAgenda.cs apps/powerpoint-vsto/PresentationAgenda.cs apps/powerpoint-vsto/ServiceConnections.cs apps/powerpoint-vsto/DataLinkManager.cs apps/powerpoint-vsto/DemoTools.cs apps/powerpoint-vsto/DataSources.cs tests/s0/NativeFormattingTests.cs tests/s0/PresentationQualityTests.cs tests/s0/NativeChartControlTests.cs tests/s0/ExcelRangeMappingTests.cs tests/s0/DataSourceTests.cs tests/s0/ChartAnnotationTests.cs tests/s0/ContextPropertiesTests.cs tests/s0/ContextPanelModelTests.cs tests/s0/ContextFormattingTests.cs tests/s0/ContextChartFormattingTests.cs tests/s0/XmlPartUpdateTests.cs tests/s0/ProductivityToolTests.cs tests/s0/IndicatorElementTests.cs tests/s0/UniversalConnectorTests.cs tests/s0/TextShapeElementTests.cs tests/s0/ProcessFlowTests.cs tests/s0/ChapterAgendaTests.cs tests/s0/PresentationAgendaTests.cs tests/s0/ServiceConnectionTests.cs tests/s0/DataLinkManagerTests.cs apps/powerpoint-vsto/DemoInputs.cs apps/powerpoint-vsto/DemoLinks.cs apps/powerpoint-vsto/FeatureInventory.cs apps/powerpoint-vsto/PowerPointHost.cs apps/powerpoint-vsto/Contracts.cs apps/powerpoint-vsto/MetadataCodec.cs tests/s0/ContextForegroundPolicy.cs tests/s0/ContextForegroundPrompt.cs tests/s0/DemoContractTests.cs
    if($LASTEXITCODE) { throw 'Demo contract compilation failed.' }
    Copy-Item -LiteralPath apps/powerpoint-vsto/App.config -Destination artifacts/demo-contracts/DemoContractTests.exe.config -Force
    & ./artifacts/demo-contracts/DemoContractTests.exe apps/powerpoint-vsto/ThisAddIn.cs artifacts/demo-contracts
